const generateBtn = document.getElementById('generateBtn');
const userPrompt = document.getElementById('userPrompt');
const generatedText = document.getElementById('generatedText');
const sentimentValue = document.getElementById('sentimentValue');
const sentimentConfidence = document.getElementById('sentimentConfidence');
const btnText = document.querySelector('.btn-text');
const btnLoader = document.querySelector('.btn-loader');
const sentimentBadge = document.getElementById('sentimentBadge');

// Sentiment colors
const sentimentColors = {
    'POSITIVE': '#22c55e',
    'NEGATIVE': '#ef4444',
    'NEUTRAL': '#6b7280'
};

// Sentiment labels
const sentimentLabels = {
    'POSITIVE': 'Positive',
    'NEGATIVE': 'Negative',
    'NEUTRAL': 'Neutral'
};

// Show loading state
function setLoading(loading) {
    if (loading) {
        btnText.textContent = 'Generating...';
        btnLoader.style.display = 'block';
        generateBtn.disabled = true;
        generatedText.innerHTML = '<p class="placeholder-text">AI is generating your content...</p>';
    } else {
        btnText.textContent = 'Generate Text';
        btnLoader.style.display = 'none';
        generateBtn.disabled = false;
    }
}

// Display sentiment result
function displaySentiment(sentiment, confidence) {
    const color = sentimentColors[sentiment] || sentimentColors['NEUTRAL'];
    sentimentValue.textContent = sentimentLabels[sentiment] || sentiment;
    sentimentConfidence.textContent = `Confidence: ${(confidence * 100).toFixed(1)}%`;
    sentimentBadge.style.backgroundColor = color;
    sentimentValue.style.color = 'white';
    sentimentConfidence.style.color = 'rgba(255,255,255,0.9)';
}

// Display generated text
function displayText(text) {
    generatedText.innerHTML = `<p>${text}</p>`;
}

// Handle form submission
generateBtn.addEventListener('click', async () => {
    const prompt = userPrompt.value.trim();

    if (!prompt) {
        alert('Please enter a topic or text to generate');
        return;
    }

    try {
        setLoading(true);

        const response = await fetch('/', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/x-www-form-urlencoded',
            },
            body: `user_prompt=${encodeURIComponent(prompt)}`
        });

        if (!response.ok) {
            throw new Error('Failed to generate text');
        }

        const data = await response.json();

        // Assuming the backend returns both sentiment and text
        // If backend only returns text, you may need to adjust this
        displayText(data.generated_text || 'No text generated');

        // Reset sentiment display
        sentimentValue.textContent = '--';
        sentimentConfidence.textContent = '--';
        sentimentBadge.style.backgroundColor = '#6b7280';
        sentimentValue.style.color = 'white';
        sentimentConfidence.style.color = 'rgba(255,255,255,0.9)';

    } catch (error) {
        console.error('Error:', error);
        generatedText.innerHTML = '<p class="error-text">Error generating text. Please try again later.</p>';
        alert('An error occurred. Please check the console for details.');
    } finally {
        setLoading(false);
    }
});

// Allow Ctrl+Enter to submit
userPrompt.addEventListener('keydown', (e) => {
    if (e.ctrlKey && e.key === 'Enter') {
        generateBtn.click();
    }
});

/* Reset and Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

:root {
    --primary-color: #6366f1;
    --primary-dark: #4f46e5;
    --primary-light: #818cf8;
    --secondary-color: #10b981;
    --danger-color: #ef4444;
    --neutral-color: #6b7280;
    --background-color: #f8fafc;
    --card-background: #ffffff;
    --text-primary: #1e293b;
    --text-secondary: #64748b;
    --border-color: #e2e8f0;
    --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
    --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
    --radius-md: 0.5rem;
    --radius-lg: 0.75rem;
    --radius-xl: 1rem;
    --transition: all 0.3s ease;
}

body {
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    min-height: 100vh;
    color: var(--text-primary);
    line-height: 1.6;
}

/* Header Styles */
header {
    background: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(10px);
    box-shadow: var(--shadow-md);
    position: sticky;
    top: 0;
    z-index: 1000;
}

nav {
    max-width: 1200px;
    margin: 0 auto;
    padding: 1rem 2rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-size: 1.5rem;
    font-weight: 700;
    background: linear-gradient(135deg, var(--primary-color), var(--primary-dark));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

nav ul {
    list-style: none;
    display: flex;
    gap: 2rem;
}

nav a {
    color: var(--text-primary);
    text-decoration: none;
    font-weight: 500;
    transition: var(--transition);
    position: relative;
}

nav a:hover {
    color: var(--primary-color);
}

nav a::after {
    content: '';
    position: absolute;
    bottom: -4px;
    left: 0;
    width: 0;
    height: 2px;
    background: var(--primary-color);
    transition: var(--transition);
}

nav a:hover::after {
    width: 100%;
}

/* Main Content */
main {
    max-width: 1200px;
    margin: 0 auto;
    padding: 2rem;
    min-height: calc(100vh - 80px);
}

/* Hero Section */
.hero {
    text-align: center;
    padding: 4rem 2rem;
    color: white;
}

.hero-content {
    max-width: 800px;
    margin: 0 auto;
}

.hero h1 {
    font-size: 3rem;
    font-weight: 800;
    margin-bottom: 1.5rem;
    line-height: 1.2;
    text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.2);
}

.hero p {
    font-size: 1.25rem;
    opacity: 0.95;
    line-height: 1.8;
}

/* Generator Container */
.generator-container {
    display: grid;
    grid-template-columns: 1fr;
    gap: 2rem;
    margin-top: 3rem;
}

@media (min-width: 768px) {
    .generator-container {
        grid-template-columns: 1fr 1fr;
    }
}

/* Input Section */
.input-section {
    background: var(--card-background);
    padding: 2rem;
    border-radius: var(--radius-xl);
    box-shadow: var(--shadow-lg);
}

.input-section h2 {
    font-size: 1.5rem;
    color: var(--text-primary);
    margin-bottom: 1.5rem;
}

.input-wrapper {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

#userPrompt {
    width: 100%;
    padding: 1rem 1.25rem;
    border: 2px solid var(--border-color);
    border-radius: var(--radius-lg);
    font-size: 1rem;
    font-family: inherit;
    resize: vertical;
    transition: var(--transition);
    background: var(--background-color);
}

#userPrompt:focus {
    outline: none;
    border-color: var(--primary-color);
    box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.1);
}

#userPrompt::placeholder {
    color: var(--text-secondary);
}

.generate-btn {
    background: linear-gradient(135deg, var(--primary-color), var(--primary-dark));
    color: white;
    border: none;
    padding: 1rem 2rem;
    border-radius: var(--radius-lg);
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition);
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    min-width: 200px;
}

.generate-btn:hover:not(:disabled) {
    transform: translateY(-2px);
    box-shadow: var(--shadow-lg);
}

.generate-btn:active:not(:disabled) {
    transform: translateY(0);
}

.generate-btn:disabled {
    opacity: 0.7;
    cursor: not-allowed;
}

.hint {
    font-size: 0.875rem;
    color: var(--text-secondary);
    font-style: italic;
}

/* Results Section */
.results-section {
    background: var(--card-background);
    padding: 2rem;
    border-radius: var(--radius-xl);
    box-shadow: var(--shadow-lg);
}

.results-section h2 {
    font-size: 1.5rem;
    color: var(--text-primary);
    margin-bottom: 1.5rem;
}

/* Sentiment Badge */
.sentiment-badge {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 1.5rem;
    border-radius: var(--radius-lg);
    background: linear-gradient(135deg, var(--neutral-color), var(--text-secondary));
    color: white;
    margin-bottom: 1.5rem;
    transition: var(--transition);
}

.sentiment-label {
    font-size: 0.875rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    opacity: 0.9;
    margin-bottom: 0.5rem;
}

.sentiment-value {
    font-size: 2rem;
    font-weight: 700;
}

.sentiment-confidence {
    font-size: 0.875rem;
    opacity: 0.9;
}

/* Output Container */
.output-container {
    margin-top: 1.5rem;
}

.output-label {
    font-size: 0.875rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: var(--text-secondary);
    margin-bottom: 0.75rem;
}

.output-content {
    background: var(--background-color);
    padding: 1.5rem;
    border-radius: var(--radius-lg);
    border: 2px solid var(--border-color);
    min-height: 200px;
    transition: var(--transition);
}

.output-content p {
    font-size: 1.125rem;
    line-height: 1.8;
    color: var(--text-primary);
}

.placeholder-text {
    color: var(--text-secondary);
    font-style: italic;
}

.error-text {
    color: var(--danger-color);
    font-weight: 500;
}

/* Loading Spinner */
.btn-loader {
    width: 20px;
    height: 20px;
    border: 3px solid rgba(255, 255, 255, 0.3);
    border-radius: 50%;
    border-top-color: white;
    animation: spin 1s ease-in-out infinite;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

/* Footer */
footer {
    background: rgba(0, 0, 0, 0.8);
    color: white;
    padding: 1.5rem;
    text-align: center;
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    backdrop-filter: blur(10px);
}

footer p {
    font-size: 0.875rem;
    opacity: 0.9;
}

/* Responsive Design */
@media (max-width: 768px) {
    .hero h1 {
        font-size: 2rem;
    }

    .hero p {
        font-size: 1rem;
    }

    nav {
        flex-direction: column;
        gap: 1rem;
    }

    nav ul {
        gap: 1rem;
        font-size: 0.875rem;
    }

    .generator-container {
        grid-template-columns: 1fr;
    }

    .input-section,
    .results-section {
        padding: 1.5rem;
    }

    .hero {
        padding: 3rem 1rem;
    }
}

@media (max-width: 480px) {
    .hero h1 {
        font-size: 1.5rem;
    }

    .hero p {
        font-size: 0.875rem;
    }

    nav ul {
        flex-wrap: wrap;
        justify-content: center;
    }

    .generate-btn {
        width: 100%;
    }
}
